'use strict';
(function(){
 const host=document.createElement('section');host.className='access-panel';host.innerHTML=`<details><summary>Telefon orqali kirish</summary><form id="phone-form"><label>Telefon raqami<input name="phone" type="tel" placeholder="+998901234567" required maxlength="20" autocomplete="tel"></label><label>Ismingiz (yangi hisob uchun)<input name="name" required maxlength="40" autocomplete="name"></label><button type="submit">SMS kod olish</button></form><form id="code-form" hidden><label>SMS kod<input name="code" required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code"></label><button type="submit">Tasdiqlash</button></form></details><details><summary>Parolni unutdingizmi?</summary><form id="recover-form"><label>Email<input name="email" type="email" required autocomplete="email"></label><button>Tiklash kodini olish</button></form><form id="reset-form"><label>Emailga kelgan kod<input name="token" required maxlength="100" autocomplete="off"></label><label>Yangi parol<input name="password" type="password" required maxlength="128" autocomplete="new-password"></label><button>Parolni yangilash</button></form></details><p id="access-status" role="status"></p>`;
 const target=document.querySelector('#auth-form');if(!target)return;target.after(host);let challenge='',name='';const status=host.querySelector('#access-status');
 async function request(path,body){const r=await fetch('/api/access/'+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'So‘rov bajarilmadi.');return data}
 function bind(id,fn){const form=host.querySelector(id);form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('button');if(b.disabled)return;b.disabled=true;status.textContent='Kutilmoqda…';try{await fn(Object.fromEntries(new FormData(form)))}catch(e){status.textContent=e.message}finally{b.disabled=false}})}
 bind('#phone-form',async d=>{const data=await request('code',{phone:d.phone});challenge=data.challenge;name=d.name;host.querySelector('#code-form').hidden=false;status.textContent='SMS kod yuborildi. 5 daqiqa amal qiladi.'});
 bind('#code-form',async d=>{await request('verify',{challenge,name,code:d.code});try{localStorage.setItem('baraka-auth-event',JSON.stringify({action:'login',nonce:crypto.randomUUID()}))}catch{}location.replace('app.html#today')});
 bind('#recover-form',async d=>{const data=await request('recover',d);status.textContent=data.message});
 bind('#reset-form',async d=>{await request('reset',d);status.textContent='Parol yangilandi. Yangi parol bilan kiring.';host.querySelector('#reset-form').reset()});
 globalThis.BarakaLocale?.paint();
})();
